begin;

create table if not exists public.tts_topic_catalog (
  rentability_topic_id text primary key,
  topic_label text not null,
  canonical_area text,
  main_specialty text,
  rentability_tier text check (rentability_tier in ('MUY_ALTA','ALTA','MEDIA','BAJA')),
  rentability_score numeric(6,2),
  status text not null check (status in ('PARTIAL','COMPLETE')),
  primary_code text not null unique,
  tts_version text,
  catalog_version text not null,
  part_count integer not null default 0 check (part_count >= 0),
  part_codes jsonb not null default '[]'::jsonb,
  estimated_minutes numeric(8,1),
  package_relative_folder text,
  complete_txt_file text,
  complete_markdown_file text,
  source_status text,
  source_package text not null,
  source_package_sha256 text not null check (source_package_sha256 ~ '^[0-9a-f]{64}$'),
  reviewed_as_of date,
  available_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.tts_topic_catalog is
  'Catálogo separado del banco clínico: disponibilidad de lecturas TTS por rentability_topic_id.';

create index if not exists tts_topic_catalog_status_idx
  on public.tts_topic_catalog (status, primary_code);
create index if not exists tts_topic_catalog_tier_score_idx
  on public.tts_topic_catalog (rentability_tier, rentability_score desc);

alter table public.tts_topic_catalog enable row level security;

do $policy$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname='public' and tablename='tts_topic_catalog'
      and policyname='tts_topic_catalog_read_authenticated'
  ) then
    create policy tts_topic_catalog_read_authenticated
      on public.tts_topic_catalog for select to authenticated using (true);
  end if;
end
$policy$;

grant select on table public.tts_topic_catalog to authenticated;

