do $precheck$
declare
  v_seed_count integer;
  v_distinct_topics integer;
  v_distinct_codes integer;
  v_linked_count integer;
begin
  select count(*), count(distinct rentability_topic_id), count(distinct primary_code)
    into v_seed_count, v_distinct_topics, v_distinct_codes
  from _tts_seed_v061;

  select count(*) into v_linked_count
  from _tts_seed_v061 s
  where exists (
    select 1 from public.questions q
    where q.rentability_topic_id=s.rentability_topic_id
  );

  if v_seed_count<>89 or v_distinct_topics<>89 or v_distinct_codes<>89 then
    raise exception 'Semilla TTS inválida: filas %, temas %, códigos %; se esperaban 89/89/89',
      v_seed_count, v_distinct_topics, v_distinct_codes;
  end if;
  if v_linked_count<>89 then
    raise exception 'Vínculo taxonómico incompleto: % de 89 topic_id existen en questions', v_linked_count;
  end if;
end
$precheck$;

insert into public.tts_topic_catalog (
  rentability_topic_id, topic_label, canonical_area, main_specialty,
  rentability_tier, rentability_score, status, primary_code, tts_version,
  catalog_version, part_count, part_codes, estimated_minutes,
  package_relative_folder, complete_txt_file, complete_markdown_file,
  source_status, source_package, source_package_sha256, reviewed_as_of,
  available_at, updated_at
)
select
  rentability_topic_id, topic_label, canonical_area, main_specialty,
  rentability_tier, rentability_score, status, primary_code, tts_version,
  catalog_version, part_count, part_codes, estimated_minutes,
  package_relative_folder, complete_txt_file, complete_markdown_file,
  source_status, source_package, source_package_sha256, reviewed_as_of,
  now(), now()
from _tts_seed_v061
on conflict (rentability_topic_id) do update set
  topic_label=excluded.topic_label,
  canonical_area=excluded.canonical_area,
  main_specialty=excluded.main_specialty,
  rentability_tier=excluded.rentability_tier,
  rentability_score=excluded.rentability_score,
  status=excluded.status,
  primary_code=excluded.primary_code,
  tts_version=excluded.tts_version,
  catalog_version=excluded.catalog_version,
  part_count=excluded.part_count,
  part_codes=excluded.part_codes,
  estimated_minutes=excluded.estimated_minutes,
  package_relative_folder=excluded.package_relative_folder,
  complete_txt_file=excluded.complete_txt_file,
  complete_markdown_file=excluded.complete_markdown_file,
  source_status=excluded.source_status,
  source_package=excluded.source_package,
  source_package_sha256=excluded.source_package_sha256,
  reviewed_as_of=excluded.reviewed_as_of,
  updated_at=excluded.updated_at;

do $postcheck$
declare v_count integer;
begin
  select count(*) into v_count
  from public.tts_topic_catalog c
  join _tts_seed_v061 s using (rentability_topic_id)
  where c.status='COMPLETE' and c.primary_code=s.primary_code
    and c.catalog_version='V061';
  if v_count<>89 then
    raise exception 'Catálogo incompleto después del UPSERT: % de 89', v_count;
  end if;
end
$postcheck$;

commit;
